parameters.jsCode:
// Récupérer le résultat de l'analyse IA
const aiOutput = $input.first().json.output;
let criteria;
try {
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
  criteria = JSON.parse(jsonMatch ? jsonMatch[0] : aiOutput);
} catch(e) {
  criteria = {
    titre_poste: 'candidat',
    localisation: '',
    competences_cles: [],
    mots_cles: []
  };
}

const titre = criteria.titre_poste || 'candidat';
const ville = criteria.localisation || '';
const competences = criteria.competences_cles || [];
const motsCles = criteria.mots_cles || [];
const experience = criteria.niveau_experience || '';

// Stocker les critères pour les nœuds suivants
const criteriaStr = JSON.stringify(criteria);

// Générer les requêtes de recherche Google pour chaque plateforme
const queries = [];

// --- LinkedIn (3 requêtes variées) ---
queries.push({
  query: `site:linkedin.com/in "${titre}" "${ville}"`,
  platform: 'LinkedIn'
});
if (competences.length > 0) {
  queries.push({
    query: `site:linkedin.com/in ${titre} ${competences.slice(0, 3).join(' ')} ${ville}`,
    platform: 'LinkedIn'
  });
}
if (motsCles.length > 0) {
  queries.push({
    query: `site:linkedin.com/in ${motsCles.slice(0, 4).join(' ')} ${ville}`,
    platform: 'LinkedIn'
  });
}

// --- Indeed (2 requêtes) ---
queries.push({
  query: `site:indeed.fr "${titre}" "${ville}"`,
  platform: 'Indeed'
});
queries.push({
  query: `site:indeed.fr ${titre} ${competences.slice(0, 2).join(' ')} ${ville}`,
  platform: 'Indeed'
});

// --- Welcome to the Jungle (2 requêtes) ---
queries.push({
  query: `site:welcometothejungle.com "${titre}" "${ville}"`,
  platform: 'WTTJ'
});
if (motsCles.length > 0) {
  queries.push({
    query: `site:welcometothejungle.com ${motsCles.slice(0, 3).join(' ')} ${ville}`,
    platform: 'WTTJ'
  });
}

// --- Recherche web générale (2 requêtes) ---
queries.push({
  query: `"${titre}" "${ville}" CV OR profil OR resume ${experience}`,
  platform: 'Web'
});
queries.push({
  query: `"${titre}" "${ville}" ${competences.slice(0, 3).join(' ')} profil professionnel`,
  platform: 'Web'
});

return queries.map(q => ({ json: { ...q, criteria: criteriaStr } }));

// Agréger tous les résultats Google et dédupliquer
const allItems = $input.all();
const candidates = [];
const seen = new Set();

// Récupérer les critères depuis le premier item
let criteria = {};
try {
  const firstWithCriteria = allItems.find(item => item.json.criteria);
  if (firstWithCriteria) {
    criteria = JSON.parse(firstWithCriteria.json.criteria);
  }
} catch(e) {}

for (const item of allItems) {
  const results = item.json.items || [];

  for (const result of results) {
    const url = result.link || '';

    // Ignorer les doublons par URL
    if (seen.has(url)) continue;
    seen.add(url);

    // Ignorer les pages non pertinentes (pages d'accueil, offres d'emploi génériques)
    if (url.match(/\/(jobs|offres|recherche|search|login|signup)\/?$/)) continue;

    // Déterminer la plateforme source
    let plateforme = 'Web';
    if (url.includes('linkedin.com')) plateforme = 'LinkedIn';
    else if (url.includes('indeed.')) plateforme = 'Indeed';
    else if (url.includes('welcometothejungle')) plateforme = 'WTTJ';

    candidates.push({
      nom: (result.title || 'Inconnu').replace(/ \| LinkedIn$| - Indeed| \| Welcome to the Jungle$/gi, '').trim(),
      url: url,
      plateforme: plateforme,
      snippet: (result.snippet || '').replace(/\n/g, ' ').trim(),
      titre_page: result.title || ''
    });
  }
}

// Limiter à 50 candidats pour l'évaluation IA (sera réduit à 30 après scoring)
const topCandidates = candidates.slice(0, 50);

return [{
  json: {
    candidates: topCandidates,
    criteria: criteria,
    total_brut: candidates.length
  }
}];

