// Parser la sortie de l'IA et formater pour le CSV
const aiOutput = $input.first().json.output;
let candidates;

try {
  // Extraire le tableau JSON de la réponse
  const match = aiOutput.match(/\[[\s\S]*\]/);
  candidates = JSON.parse(match ? match[0] : aiOutput);
} catch(e) {
  // Fallback : retourner une erreur lisible
  return [{
    json: {
      'Erreur': 'Impossible de parser les résultats IA',
      'Sortie brute': aiOutput.substring(0, 500)
    }
  }];
}

// Trier par score global décroissant et prendre les 30 meilleurs
candidates.sort((a, b) => (b.score_global || 0) - (a.score_global || 0));
const top30 = candidates.filter(c => c.score_global > 0).slice(0, 30);

// Formater chaque candidat comme une ligne CSV
return top30.map((c, index) => ({
  json: {
    'Rang': index + 1,
    'Nom': c.nom || '',
    'Titre / Poste actuel': c.titre || '',
    'Localisation': c.localisation || '',
    'Plateforme': c.plateforme || '',
    'URL Profil': c.url || '',
    'Score Global (/100)': c.score_global || 0,
    'Score Compétences (/100)': c.score_competences || 0,
    'Score Géographie (/100)': c.score_geographie || 0,
    'Score Expérience (/100)': c.score_experience || 0,
    'Expérience Fermeture Industrielle / Équipement Quai': c.experience_domaine_industriel || 'non évalué',
    'Commentaire': c.commentaire || ''
  }
}));
